  const modal=document.getElementById('apiPolicyModal'),form=document.getElementById('apiPolicyForm'),create=document.getElementById('apiKeyForm');
  const normalize=t=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const matches=(text,query)=>normalize(query).split(/\s+/).filter(Boolean).every(word=>normalize(text).includes(word));
  const presets={individual:['channels:read','whatsapp:send','whatsapp:status'],bulk:['channels:read','whatsapp:bulk','whatsapp:status'],complete:['channels:read','whatsapp:send','whatsapp:bulk','whatsapp:status'],general:['channels:read','messages:send','messages:receive','nivo:context']};
  const refresh=container=>{if(!container)return;const query=container.querySelector('.api-scope-search')?.value||'';const cards=[...container.querySelectorAll('.api-scope-card')];let selected=0,visible=0;cards.forEach(card=>{const check=card.querySelector('input');card.classList.toggle('selected',check.checked);selected+=+check.checked;card.hidden=!matches(card.textContent+' '+check.value+' '+({'whatsapp:send':'v1/whatsapp/send individual archivo adjunto plantilla texto','whatsapp:bulk':'v1/whatsapp/send lote batch campaña múltiples destinatarios','whatsapp:status':'v1/whatsapp/status consulta entrega lectura error','channels:read':'v1/channels id canal'}[check.value]||''),query);visible+=+!card.hidden;});const count=container.querySelector('.api-scope-count');if(count)count.textContent=selected+' seleccionados';const empty=container.querySelector('.api-scope-empty');if(empty)empty.hidden=visible!==0;const keys=cards.filter(c=>c.querySelector('input').checked).map(c=>c.dataset.scope);container.querySelectorAll('.api-scope-preset').forEach(b=>{const values=presets[b.dataset.profile]||[];const active=values.length===keys.length&&values.every(x=>keys.includes(x));b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});};
  const setPermissions=(container,values)=>{if(!container)return;container.querySelectorAll('input[name="scopes[]"]').forEach(check=>check.checked=values.includes(check.value));const search=container.querySelector('.api-scope-search');if(search)search.value='';refresh(container);};
  [create,form].filter(Boolean).forEach(container=>{container.querySelector('.api-scope-search')?.addEventListener('input',()=>refresh(container));container.querySelectorAll('input[name="scopes[]"]').forEach(check=>check.addEventListener('change',()=>refresh(container)));container.querySelectorAll('.api-scope-preset').forEach(b=>b.addEventListener('click',()=>setPermissions(container,presets[b.dataset.profile]||[])));container.addEventListener('submit',e=>{if(e.defaultPrevented)return;if(!container.querySelector('input[name="scopes[]"]:checked')){e.preventDefault();e.stopImmediatePropagation();showNotify('error','Permisos','Seleccione al menos un permiso.');}},true);refresh(container);});
  document.querySelectorAll('.api-key-profile').forEach(b=>b.addEventListener('click',()=>{if(create){create.reset();setPermissions(create,presets[b.dataset.profile]||[]);if(window.jQuery&&jQuery.fn.select2)jQuery(create).find('select').trigger('change.select2');}}));
  const keySearch=document.getElementById('apiKeySearch'),keyCount=document.getElementById('apiKeySearchCount');const keyRows=[...document.querySelectorAll('.api-key-row')];const filterKeys=()=>{let shown=0;keyRows.forEach(row=>{row.hidden=!matches(row.textContent+' '+(row.dataset.search||''),keySearch?.value||'');shown+=+!row.hidden;});if(keyCount)keyCount.textContent=shown+' de '+keyRows.length;};keySearch?.addEventListener('input',filterKeys);filterKeys();
  document.querySelectorAll('.api-policy-edit').forEach(btn=>btn.addEventListener('click',()=>{
    if(!modal||!form)return;
    let values=[];try{values=JSON.parse(btn.dataset.scopes||'[]')}catch(_){}setPermissions(form,values);form.api_key_id.value=btn.dataset.id||'0';form.allowed_origins.value=btn.dataset.origins||'';form.allowed_ips.value=btn.dataset.ips||'';form.rate_limit_per_minute.value=btn.dataset.rate||'120';form.require_https.checked=btn.dataset.https==='1';form.active.checked=btn.dataset.active==='1';
    const name=document.getElementById('apiPolicyName');if(name)name.textContent='Clave: '+(btn.dataset.name||'API');modal.classList.add('open');
  }));
});
</script>
<?php require __DIR__.'/partials/bottom.php'; ?>